Sections:

// === CONFIG =============================================================

const W = 800, H = 600;

// === STATE =============================================================

const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const restartBtn = document.getElementById('restart');

let player; // { x, y }
let keys;
let loopId = null;

// === RESET =============================================================

function reset() {
  player = { x: W/2, y: H/2 };
  keys = new Set();
  publishState();
  startLoop();
}

// === LOOP/UPDATE =============================================================

function startLoop() {
  if (loopId !== null) cancelAnimationFrame(loopId);
  function tick(now) {
    try {
      // No physics needed for stub.
      render();
      publishState();
    } catch (err) {
      console.error('loop error', err);
    }
    loopId = requestAnimationFrame(tick);
  }
  loopId = requestAnimationFrame(tick);
}

// === RENDER =============================================================

function render() {
  ctx.fillStyle = '#05050c'; // dark background
  ctx.fillRect(0,0,W,H);
  // draw player as a small circle
  ctx.fillStyle = '#7df9ff';
  ctx.beginPath();
  ctx.arc(player.x, player.y, 6, 0, Math.PI*2);
  ctx.fill();
}

// === INPUT =============================================================

document.addEventListener('keydown', (ev) => {
  if (ev.key === 'r' || ev.key === 'R') { reset(); return; }
  keys.add(ev.key);
});

document.addEventListener('keyup', (ev) => {
  keys.delete(ev.key);
});

restartBtn.addEventListener('click', reset);

// === AUDIO (lazy) =============================================================

function beep() {}
// no audio used now

// === OBSERVABLE CONTRACT ================================================

function publishState() {
  window.__game = {
    state: 'playing',
    score: 0,
    player: {
      x: player.x,
      y: player.y,
      visible: true,
    },
    objective: 'Toggle the orbit radius to dodge obstacles.',
  };
}

// === BOOT ===============================================================

reset();

